INSERT INTO pas.policy_clauses (clause_id, product, section, title, clause_type, body, perils, keywords) VALUES
  ('HO3-I-A-1', 'HO3', 'Section I — Property Coverages', 'Coverage A — Dwelling', 'grant', 'We cover the dwelling on the residence premises shown in the Declarations, including structures attached to the dwelling, and materials and supplies located on or next to the residence premises used to construct, alter or repair the dwelling. We do not cover land, including land on which the dwelling is located.', '{}', 'fire smoke burned burnt scorched charred house home structure building walls ceiling roof kitchen garage'),
  ('HO3-I-B-1', 'HO3', 'Section I — Property Coverages', 'Coverage B — Other Structures', 'grant', 'We cover other structures on the residence premises set apart from the dwelling by clear space. The limit of liability for this coverage is 10% of the Coverage A limit and is an additional amount of insurance.', '{}', 'shed garage fence detached outbuilding workshop carport'),
  ('HO3-I-C-1', 'HO3', 'Section I — Property Coverages', 'Coverage C — Personal Property', 'grant', 'We cover personal property owned or used by an insured while it is anywhere in the world. Our limit of liability for personal property usually situated at an insured''s residence, other than the residence premises, is 10% of the Coverage C limit, or $1,000, whichever is greater.', '{}', 'belongings contents possessions furniture electronics jewelry jewellery clothes laptop television stolen taken'),
  ('HO3-I-C-2', 'HO3', 'Section I — Property Coverages', 'Special Limits of Liability', 'limit', 'Special limits apply to the following and do not increase the Coverage C limit. $200 on money, bank notes, bullion, coins and medals. $1,500 on securities, accounts, deeds and manuscripts. $1,500 on watercraft including trailers and equipment. $2,500 on theft of firearms and related equipment. $2,500 on theft of jewelry, watches, furs and precious stones. $2,500 on property used primarily for business purposes.', '{"theft"}', 'jewelry jewellery watches firearms guns cash money coins securities limit capped'),
  ('HO3-I-D-1', 'HO3', 'Section I — Property Coverages', 'Coverage D — Loss of Use', 'grant', 'If a loss covered under Section I makes that part of the residence premises where an insured resides not fit to live in, we cover the additional living expense, meaning any necessary increase in living expenses incurred so that the household can maintain its normal standard of living. Payment is for the shortest time required to repair or replace the damage, not to exceed 12 months.', '{}', 'hotel temporary accommodation living elsewhere cannot live uninhabitable displaced'),
  ('HO3-I-PERILS-1', 'HO3', 'Section I — Perils Insured Against', 'Coverage A and B — Open Perils', 'grant', 'We insure against risk of direct physical loss to property described in Coverages A and B. We do not insure, however, for loss excluded under Section I — Exclusions, or caused by the specific causes listed in this section.', '{"fire","wind","water","theft","vandalism"}', 'fire smoke wind hail storm explosion vehicle impact falling tree'),
  ('HO3-I-PERILS-2', 'HO3', 'Section I — Perils Insured Against', 'Coverage C — Named Perils', 'grant', 'We insure for direct physical loss to the property described in Coverage C caused by: fire or lightning; windstorm or hail; explosion; riot or civil commotion; aircraft; vehicles; smoke; vandalism or malicious mischief; theft; falling objects; weight of ice, snow or sleet; accidental discharge or overflow of water or steam; sudden and accidental tearing apart of a heating or air conditioning system; freezing; and sudden and accidental damage from artificially generated electrical current.', '{"fire","wind","theft","water","vandalism"}', 'fire smoke theft stolen wind hail vandalism freezing burst discharge overflow'),
  ('HO3-I-EXCL-1', 'HO3', 'Section I — Exclusions', 'Ordinance or Law', 'exclusion', 'We do not insure for loss caused directly or indirectly by the enforcement of any ordinance or law regulating the construction, repair or demolition of a building or other structure, unless specifically provided under this policy.', '{}', 'building code upgrade permit ordinance bring up to code inspector required'),
  ('HO3-I-EXCL-2', 'HO3', 'Section I — Exclusions', 'Earth Movement', 'exclusion', 'We do not insure for loss caused directly or indirectly by earth movement, meaning earthquake including land shock waves, landslide, mudslide, mudflow, subsidence, sinkhole, or earth sinking, rising or shifting. This exclusion does not apply to direct loss by fire or explosion resulting from earth movement.', '{"earthquake"}', 'earthquake tremor shook shaking crack cracked foundation sank sinking shifted subsidence landslide'),
  ('HO3-I-EXCL-3', 'HO3', 'Section I — Exclusions', 'Water Damage', 'exclusion', 'We do not insure for loss caused directly or indirectly by water damage, meaning: flood, surface water, waves, tidal water, overflow of a body of water, or spray from any of these, whether or not driven by wind; water which backs up through sewers or drains or which overflows from a sump; or water below the surface of the ground, including water which exerts pressure on or seeps through a building, sidewalk, driveway, foundation, swimming pool or other structure.', '{"water","flood"}', 'flood flooding creek river stream rain rainwater storm water surface water rose came up basement groundwater sewer backup drain overflowed'),
  ('HO3-I-EXCL-3b', 'HO3', 'Section I — Exclusions', 'Water Damage — Sudden and Accidental Exception', 'grant', 'The water damage exclusion does not apply to sudden and accidental discharge or overflow of water or steam from within a plumbing, heating, air conditioning or automatic fire protective sprinkler system, or from within a household appliance. We do not cover loss to the system or appliance from which the water escaped, nor loss caused by continuous or repeated seepage or leakage over a period of weeks, months or years.', '{"water"}', 'burst pipe pipes plumbing supply line hose washing machine dishwasher water heater appliance sudden leak ceiling came through upstairs'),
  ('HO3-I-EXCL-4', 'HO3', 'Section I — Exclusions', 'Neglect', 'exclusion', 'We do not insure for loss caused by neglect, meaning the insured''s failure to use all reasonable means to save and preserve property at and after the time of a loss.', '{}', 'failed to protect left open neglected did nothing tarp board up'),
  ('HO3-I-EXCL-5', 'HO3', 'Section I — Exclusions', 'Intentional Loss', 'exclusion', 'We do not insure for loss arising out of any act an insured commits or conspires to commit with the intent to cause a loss. In the event of such loss, no insured is entitled to coverage, even insureds who did not commit or conspire to commit the act causing the loss.', '{"fire","vandalism","theft"}', 'deliberate deliberately on purpose intentional arson set fire staged'),
  ('HO3-I-EXCL-6', 'HO3', 'Section I — Exclusions', 'Wear and Tear, Deterioration', 'exclusion', 'We do not insure for loss caused by wear and tear, marring, deterioration, mechanical breakdown, latent defect, inherent vice, rust, mold, wet or dry rot, smog, settling, shrinking, bulging or expansion of pavements, foundations, walls, floors, roofs or ceilings, or birds, vermin, rodents or insects.', '{}', 'leak leaking leaked slow gradual gradually over time for a while long standing years months shingles aged old worn worn out end of life sagging sagged discoloured discolored black mould mould rot rotting rusted deteriorated deteriorating wear tear maintenance'),
  ('HO3-I-EXCL-7', 'HO3', 'Section I — Exclusions', 'Vacancy', 'exclusion', 'We do not insure for loss by vandalism or malicious mischief, theft, or water damage from freezing if the dwelling has been vacant for more than 60 consecutive days immediately before the loss. A dwelling being constructed is not considered vacant.', '{"vandalism","theft","water"}', 'empty unoccupied nobody living vacant moved out care home abandoned standing empty'),
  ('HO3-I-EXCL-8', 'HO3', 'Section I — Exclusions', 'Business Property and Activities', 'exclusion', 'We do not insure for loss arising out of or in connection with a business conducted from the residence premises, except as specifically provided. Business property on the residence premises is subject to the special limit stated in Coverage C.', '{}', 'business work office clients customers home business commercial'),
  ('HO3-I-COND-1', 'HO3', 'Section I — Conditions', 'Your Duties After Loss', 'condition', 'In case of a loss to covered property, you must give prompt notice to us or our agent; protect the property from further damage and make reasonable and necessary repairs to protect it; cooperate with us in the investigation of the claim; and, within 60 days after our request, submit to us a signed, sworn proof of loss.', '{}', 'report notify tell us police report proof of loss paperwork documents cooperate inspection'),
  ('HO3-I-COND-2', 'HO3', 'Section I — Conditions', 'Deductible', 'condition', 'Unless otherwise noted in this policy, the following deductible provision applies: with respect to any one loss, we will pay only that part of the total of all loss payable that exceeds the deductible amount shown in the Declarations.', '{}', 'deductible excess out of pocket first part'),
  ('HO3-I-COND-3', 'HO3', 'Section I — Conditions', 'Loss Settlement', 'condition', 'Covered property losses are settled as follows. Personal property and structures that are not buildings at actual cash value at the time of loss, not exceeding the amount necessary to repair or replace. Buildings under Coverage A or B at replacement cost without deduction for depreciation, provided the building is insured for at least 80% of its full replacement cost at the time of loss.', '{}', 'replacement cost actual cash value depreciation payout settle how much'),
  ('HO3-I-COND-4', 'HO3', 'Section I — Conditions', 'Concealment or Fraud', 'condition', 'We provide coverage to no insured who, whether before or after a loss, has intentionally concealed or misrepresented any material fact or circumstance, engaged in fraudulent conduct, or made false statements relating to this insurance.', '{}', 'lied lying false statement exaggerated misrepresented concealed fraud dishonest'),
  ('HO3-I-COND-5', 'HO3', 'Section I — Conditions', 'Suit Against Us', 'condition', 'No action can be brought against us unless there has been full compliance with all of the terms under Section I of this policy and the action is started within two years after the date of loss.', '{}', 'sue lawsuit legal action time limit deadline'),
  ('HO3-II-E-1', 'HO3', 'Section II — Liability Coverages', 'Coverage E — Personal Liability', 'grant', 'If a claim is made or a suit is brought against an insured for damages because of bodily injury or property damage caused by an occurrence to which this coverage applies, we will pay up to our limit of liability for the damages for which an insured is legally liable, and provide a defense at our expense by counsel of our choice.', '{"liability"}', 'guest visitor injured hurt slipped fell liability sued lawyer claim against us'),
  ('HO3-II-F-1', 'HO3', 'Section II — Liability Coverages', 'Coverage F — Medical Payments to Others', 'grant', 'We will pay the necessary medical expenses incurred or medically ascertained within three years from the date of an accident causing bodily injury. This coverage does not apply to you or regular residents of your household other than residence employees.', '{"liability"}', 'medical bills hospital ambulance treatment injured guest'),
  ('HO3-II-EXCL-1', 'HO3', 'Section II — Exclusions', 'Motor Vehicle Liability', 'exclusion', 'Coverage E and Coverage F do not apply to bodily injury or property damage arising out of the ownership, maintenance, occupancy, operation, use, loading or unloading of motor vehicles. Motor vehicle liability is addressed under a separate automobile policy.', '{"liability","collision"}', 'car vehicle driving auto motor accident road'),
  ('HO3-DEF-1', 'HO3', 'Definitions', 'Occurrence', 'definition', 'Occurrence means an accident, including continuous or repeated exposure to substantially the same general harmful conditions, which results during the policy period in bodily injury or property damage.', '{}', 'occurrence accident incident event'),
  ('HO3-DEF-2', 'HO3', 'Definitions', 'Residence Premises', 'definition', 'Residence premises means the one-family dwelling where you reside, the two-, three- or four-family dwelling where you reside in at least one of the family units, or that part of any other building where you reside, and which is shown as the residence premises in the Declarations.', '{}', 'home address residence where i live property'),
  ('HO3-DEF-3', 'HO3', 'Definitions', 'Actual Cash Value', 'definition', 'Actual cash value means the cost to repair or replace the damaged property with property of like kind and quality, less an allowance for physical depreciation based on the age and condition of the property at the time of loss.', '{}', 'depreciation value worth age condition used'),
  ('HO4-I-C-1', 'HO4', 'Section I — Property Coverages', 'Coverage C — Personal Property (Renters)', 'grant', 'We cover personal property owned or used by an insured while it is anywhere in the world, against the named perils listed in this form. This policy provides no coverage for the dwelling structure itself, which remains the responsibility of the property owner.', '{"fire","theft","water","wind"}', 'renters tenant belongings contents possessions apartment flat stolen taken furniture electronics'),
  ('HO4-I-D-1', 'HO4', 'Section I — Property Coverages', 'Coverage D — Loss of Use (Renters)', 'grant', 'If a covered loss makes the described premises not fit to live in, we cover the necessary increase in living expenses incurred so the household can maintain its normal standard of living, for the shortest time required to repair or replace the premises, not to exceed 12 months.', '{}', 'hotel temporary accommodation cannot live displaced renters'),
  ('HO4-I-EXCL-1', 'HO4', 'Section I — Exclusions', 'Structural Damage', 'exclusion', 'We do not insure for loss to the building structure, fixtures, or permanently installed systems of the described premises. Coverage under this form is limited to the personal property of the insured and to loss of use.', '{"fire","water","wind"}', 'building structure landlord walls fixtures not my building'),
  ('AUTO-COLL-1', 'AUTO', 'Part D — Coverage for Damage to Your Auto', 'Collision Coverage', 'grant', 'We will pay for direct and accidental loss to your covered auto caused by collision, meaning the upset of your covered auto or its impact with another vehicle or object, less the applicable deductible shown in the Declarations for that vehicle.', '{"collision"}', 'crash collision hit rear ended accident bumper collided impact barrier'),
  ('AUTO-COMP-1', 'AUTO', 'Part D — Coverage for Damage to Your Auto', 'Other Than Collision Coverage', 'grant', 'We will pay for direct and accidental loss to your covered auto not caused by collision, including loss caused by missiles or falling objects, fire, theft or larceny, explosion, earthquake, windstorm, hail, water, flood, malicious mischief or vandalism, riot, and contact with a bird or animal, less the applicable deductible.', '{"theft","fire","wind","vandalism","water"}', 'stolen theft vandalism fire hail flood glass windscreen windshield animal deer tree branch'),
  ('AUTO-LIAB-1', 'AUTO', 'Part A — Liability Coverage', 'Liability Coverage', 'grant', 'We will pay damages for bodily injury or property damage for which any insured becomes legally responsible because of an auto accident, and will settle or defend any claim or suit asking for these damages, up to the limit of liability shown in the Declarations.', '{"liability","collision"}', 'injured other driver damage their car sued liability third party'),
  ('AUTO-EXCL-1', 'AUTO', 'Exclusions', 'Racing and Speed Contests', 'exclusion', 'We do not provide coverage for any insured for loss occurring while your covered auto is being used in, or in practice or preparation for, any prearranged or organized racing, speed or demolition contest or stunting activity.', '{"collision"}', 'racing race track day circuit speed contest stunt drifting lap autocross'),
  ('AUTO-EXCL-2', 'AUTO', 'Exclusions', 'Business and Public Livery Use', 'exclusion', 'We do not provide coverage for any insured while employed or otherwise engaged in the business of selling, repairing, servicing, storing or parking vehicles, nor while the covered auto is being used to carry persons or property for a fee. This exclusion does not apply to a share-the-expense car pool.', '{"collision","liability"}', 'uber lyft rideshare delivery taxi for hire business use courier'),
  ('AUTO-EXCL-3', 'AUTO', 'Exclusions', 'Intentional Damage', 'exclusion', 'We do not provide coverage for any insured who intentionally causes bodily injury or property damage, nor for loss to your covered auto resulting from an insured''s intentional act.', '{"collision","vandalism","fire"}', 'deliberate deliberately on purpose intentional vandalised own car'),
  ('AUTO-EXCL-4', 'AUTO', 'Exclusions', 'Wear, Freezing, Mechanical Breakdown', 'exclusion', 'We do not provide coverage for loss to your covered auto due and confined to wear and tear, freezing, mechanical or electrical breakdown or failure, or road damage to tires, unless that loss results from the total theft of your covered auto.', '{}', 'breakdown engine failure mechanical electrical tyres tires worn freezing'),
  ('AUTO-COND-1', 'AUTO', 'Part E — Duties After an Accident or Loss', 'Duties After an Accident or Loss', 'condition', 'We have no duty to provide coverage under this policy unless there has been full compliance with the following duties: prompt notice of how, when and where the accident or loss happened; cooperation in the investigation, settlement or defense of any claim; prompt notification to the police if the covered auto is stolen; and permitting us to inspect and appraise the damaged property before its repair or disposal.', '{}', 'report police notify stolen cooperate inspect appraise'),
  ('AUTO-COND-2', 'AUTO', 'Part D', 'Limit of Liability — Auto Physical Damage', 'limit', 'Our limit of liability for loss will be the lesser of the actual cash value of the stolen or damaged property, or the amount necessary to repair or replace the property with other property of like kind and quality. An adjustment for depreciation and physical condition will be made in determining actual cash value at the time of loss.', '{"collision","theft"}', 'value worth payout depreciation actual cash value how much'),
  ('AUTO-DEF-1', 'AUTO', 'Definitions', 'Your Covered Auto', 'definition', 'Your covered auto means any vehicle shown in the Declarations, a newly acquired auto, any trailer you own, and any auto or trailer you do not own while used as a temporary substitute for a vehicle shown in the Declarations that is out of normal use because of breakdown, repair, servicing, loss or destruction.', '{}', 'my car vehicle listed declarations replacement hire loaner'),
  ('ALL-GEN-1', 'ALL', 'General Provisions', 'Policy Period and Territory', 'condition', 'This policy applies only to loss, accident or occurrence which takes place during the policy period shown in the Declarations and within the policy territory. Coverage begins at 12:01 a.m. standard time on the effective date and ends at 12:01 a.m. standard time on the expiration date.', '{}', 'policy period term dates effective expiry expiration started ended before after inception in force not yet started'),
  ('ALL-GEN-2', 'ALL', 'General Provisions', 'Cancellation and Nonpayment', 'condition', 'We may cancel this policy for nonpayment of premium by mailing notice at least 10 days before the date cancellation takes effect. Where a policy has lapsed for nonpayment, no coverage is afforded for any loss occurring on or after the date of lapse, regardless of when the claim is reported.', '{}', 'lapsed lapse cancelled cancellation missed payment non payment nonpayment premium unpaid behind arrears stopped paying'),
  ('ALL-GEN-3', 'ALL', 'General Provisions', 'Misrepresentation on Application', 'condition', 'This policy was issued in reliance upon the information provided on the application. We may void this policy or deny a claim if an applicant made a material misrepresentation or omission in applying for coverage, where that misrepresentation was material to our decision to issue the policy or to the premium charged.', '{}', 'application misrepresentation lied omitted did not disclose void'),
  ('ALL-GEN-4', 'ALL', 'General Provisions', 'Other Insurance', 'condition', 'If a loss covered by this policy is also covered by other insurance, we will pay only the proportion of the loss that the limit of liability applying under this policy bears to the total amount of insurance covering the loss.', '{}', 'other insurance second policy double covered elsewhere'),
  ('ALL-GEN-5', 'ALL', 'General Provisions', 'Subrogation', 'condition', 'An insured may waive in writing before a loss all rights of recovery against any person. If not waived, we may require an assignment of rights of recovery for a loss to the extent that payment is made by us. If an assignment is sought, an insured must sign and deliver all related papers and cooperate with us.', '{}', 'subrogation recover from third party their insurer'),
  ('ALL-GEN-6', 'ALL', 'General Provisions', 'Appraisal', 'condition', 'If you and we fail to agree on the amount of loss, either may demand an appraisal of the loss. In this event, each party will choose a competent appraiser within 20 days after receiving a written request from the other, and the two appraisers will choose an umpire. A decision agreed to by any two will set the amount of loss.', '{}', 'appraisal disagree dispute amount umpire valuation');
